export default function ({ messages, previous, collected }) {
  const index = previous?.index ?? 0,
    m = messages[index];
  return {
    state: { index: index + (m ? 1 : 0), drafts: collected?.drafts ?? previous?.drafts ?? [] },
    more: !!m,
    uid: m?.uid ?? 1,
  };
}

