export default function ({ uid, from, subject, text }) {
  const body = text ?? "";
  return {
    id: String(uid),
    from: from?.email ?? "",
    subject: subject ?? "",
    classifyBody: body.slice(0, 1000),
    draftBody: body.slice(0, 2000),
  };
}

